                    writer.WriteString("auth_session_id_hash", signatureRequestInput.AuthSessionIdHash);
                else
                    writer.WriteNull("auth_session_id_hash");

            if (signatureRequestInput.AuthUserIdHashOption.IsSet)
                if (signatureRequestInput.AuthUserIdHashOption.Value != null)
                    writer.WriteString("auth_user_id_hash", signatureRequestInput.AuthUserIdHash);
                else
                    writer.WriteNull("auth_user_id_hash");

            if (signatureRequestInput.AuthUsernameHashOption.IsSet)
                if (signatureRequestInput.AuthUsernameHashOption.Value != null)
                    writer.WriteString("auth_username_hash", signatureRequestInput.AuthUsernameHash);
                else
                    writer.WriteNull("auth_username_hash");

            if (signatureRequestInput.AuthPhoneNumberHashOption.IsSet)
                if (signatureRequestInput.AuthPhoneNumberHashOption.Value != null)
                    writer.WriteString("auth_phone_number_hash", signatureRequestInput.AuthPhoneNumberHash);
                else
                    writer.WriteNull("auth_phone_number_hash");

            if (signatureRequestInput.IgnoreUnknownFieldsOption.IsSet)
                writer.WriteBoolean("ignore_unknown_fields", signatureRequestInput.IgnoreUnknownFieldsOption.Value.Value);

            if (signatureRequestInput.PrefilledValuesEditableOption.IsSet)
                writer.WriteBoolean("prefilled_values_editable", signatureRequestInput.PrefilledValuesEditableOption.Value.Value);
        }
    }
}
